cat > /tmp/equiv.mjs <<'EOF'
// Brute-force: does excluding the scoring Sphinx's own card ever change the score?
const SPHINX="sphinx";
const variety=(n)=>n>3?2*(n-3):1;
const distinct=(a)=>new Set(a.map(c=>c.monster)).size;
const withoutAt=(a,i)=>[...a.slice(0,i),...a.slice(i+1)];
const scoreExcluding=(a)=>a.reduce((t,c,i)=>c.monster===SPHINX?t+1+variety(distinct(withoutAt(a,i))):t,0);
const scoreIncluding=(a)=>a.reduce((t,c)=>c.monster===SPHINX?t+1+variety(distinct(a)):t,0);

const pool=["sphinx","chimera","orthrus","zombie","hydra","cyclops"];
let diffs=0,checked=0;
const rec=(cur,depth)=>{
  if(cur.length){checked++;if(scoreExcluding(cur)!==scoreIncluding(cur)){diffs++;if(diffs<6)console.log("DIFF",JSON.stringify(cur.map(c=>c.monster)),scoreExcluding(cur),scoreIncluding(cur));}}
  if(depth===0)return;
  for(const m of pool)rec([...cur,{monster:m}],depth-1);
};
rec([],7);
console.log("checked",checked,"diffs",diffs);
EOF
node /tmp/equiv.mjs

